let userData=null;async function usersPage(){try{let d=await api('users');userData=d;$('pageContent').innerHTML=intro('User and Role Setup','Manage users, assign roles and configure program-level access.',`<button class="btn secondary" onclick="roleModal()">＋ New Role</button><button class="btn primary" onclick="userModal()">＋ New User</button>`)+panel('User Directory',table(['Username','Full Name','Role','Status','Password Change','Actions'],d.users.map(u=>[esc(u.username),esc(u.full_name),esc(u.role_name),tag(u.status),u.must_change_password?'Required':'—',`<button class="btn secondary small" onclick="userModal(${u.id})">Edit</button>`])))+panel('Role Program Rights',`<div class="filter-row"><div class="field"><label>Select Role</label><select id="rightsRole">${d.roles.map(r=>`<option value="${r.id}">${esc(r.role_name)}</option>`).join('')}</select></div><button class="btn secondary" onclick="renderRights()">Load Rights</button><button class="btn primary" onclick="saveRights()">Save Rights</button></div><div id="rightsGrid" class="check-grid"></div>`);renderRights()}catch(e){toast(e.message,true)}}function roleModal(){modal('New Role',`<form id="roleForm" class="form-grid"><div class="full-row"><label>Role Name *</label><input name="role_name" required placeholder="e.g. Finance Manager"></div><div class="form-actions full-row"><button type="button" class="btn secondary" onclick="closeModal()">Cancel</button><button class="btn primary">Create Role</button></div></form>`);$('roleForm').onsubmit=async e=>{e.preventDefault();try{await api('saveRole',{},Object.fromEntries(new FormData(e.target)));closeModal();toast('Role created. Assign its program rights below.');await usersPage()}catch(err){toast(err.message,true)}}}
function userModal(id=0){let u=userData.users.find(x=>Number(x.id)===Number(id))||{};modal(id?'Edit User':'New User',`<form id="userForm" class="form-grid"><input type="hidden" name="id" value="${u.id||''}"><div><label>Username *</label><input name="username" required value="${esc(u.username||'')}"></div><div><label>Full Name *</label><input name="full_name" required value="${esc(u.full_name||'')}"></div><div><label>Role *</label><select name="role_id" required>${userData.roles.map(r=>`<option value="${r.id}" ${r.role_name===u.role_name?'selected':''}>${esc(r.role_name)}</option>`).join('')}</select></div><div><label>Status</label><select name="status"><option ${!u.status||u.status==='Active'?'selected':''}>Active</option><option ${u.status==='Inactive'?'selected':''}>Inactive</option></select></div><div class="full-row"><label>${id?'New Password (leave blank to keep unchanged)':'Initial Password (minimum 8 characters)'} ${id?'':'*'}</label><input name="password" type="password" ${id?'':'required'} minlength="8" autocomplete="new-password"></div><div class="form-actions full-row"><button type="button" class="btn secondary" onclick="closeModal()">Cancel</button><button class="btn primary">Save User</button></div></form>`);$('userForm').onsubmit=async e=>{e.preventDefault();try{await api('saveUser',{},Object.fromEntries(new FormData(e.target)));closeModal();toast('User saved.');await usersPage()}catch(err){toast(err.message,true)}}}function renderRights(){let role=$('rightsRole').value,roleObj=userData.roles.find(r=>String(r.id)===String(role));let allowed=new Set(userData.rights.filter(r=>r.role_name===roleObj?.role_name&&Number(r.can_view)===1).map(r=>r.code));$('rightsGrid').innerHTML=userData.programs.map(p=>`<label class="check-item"><input type="checkbox" value="${p.code}" ${allowed.has(p.code)?'checked':''}> <span><b>${esc(p.program_name)}</b><br><small class="muted">${esc(p.module_name)} · ${esc(p.code)}</small></span></label>`).join('')}function saveRights(){let role_id=Number($('rightsRole').value),rights=[...$('rightsGrid').querySelectorAll('input:checked')].map(x=>x.value);api('saveRights',{}, {role_id,rights}).then(()=>{toast('Role rights saved.');usersPage()}).catch(e=>toast(e.message,true))}
async function auditPage(){ $('pageContent').innerHTML=intro('Audit Log','Review significant application, security and financial activities.')+panel('Activity History',`<div class="filter-row"><div class="field"><label>From Date</label><input id="auditFrom" type="date" value="${today().slice(0,7)}-01"></div><div class="field"><label>To Date</label><input id="auditTo" type="date" value="${today()}"></div><button class="btn secondary" onclick="loadAudit()">Filter</button></div><div id="auditTable"></div>`);await loadAudit()}async function loadAudit(){try{let d=await api('audit',{from:$('auditFrom').value,to:$('auditTo').value});$('auditTable').innerHTML=table(['Date & Time','User','Action','Program','Record','Details','IP Address'],d.data.map(x=>[esc(x.created_at),esc(x.username),esc(x.action),esc(x.program_code||''),esc((x.record_type||'')+' '+(x.record_id||'')),esc(x.details||''),esc(x.ip_address||'')]))}catch(e){toast(e.message,true)}}
const reportNames={REPORT_LEDGER:'Account Ledger Report',REPORT_DAILY_EXPENSE:'Daily Expense-Wise Report',REPORT_EXPENSE_SUMMARY:'Expense-Wise Summary Report',REPORT_EXPENSE_DATE:'Expense Date-Wise Report',REPORT_PAYMENT:'Payment Voucher Report',REPORT_RECEIVING:'Receiving Voucher Report',REPORT_ACCOUNTS:'Accounts List'};async function reportPage(code){$('pageContent').innerHTML=intro(reportNames[code]||'Report','Select report criteria, then generate or print the report.')+panel('Report Criteria',`<div class="filter-row"><div class="field"><label>From Date</label><input type="date" id="reportFrom" value="${today().slice(0,7)}-01"></div><div class="field"><label>To Date</label><input type="date" id="reportTo" value="${today()}"></div><button class="btn primary" onclick="runReport('${code}')">Generate Report</button><button class="btn secondary" onclick="window.print()">Print</button><button class="btn secondary" onclick="exportTableCsv()">Export CSV</button></div><div id="reportResult"></div>`);await runReport(code)}let lastReportRows=[];async function runReport(code){try{let d=await api('report',{report:code,from:$('reportFrom').value,to:$('reportTo').value});lastReportRows=d.rows;let headers,rows;if(code==='REPORT_ACCOUNTS'){headers=['Account No','Account Name','Account Type','Description','Status','Opening Balance'];rows=d.rows.map(r=>[esc(r.account_no),esc(r.account_name),esc(r.type_name),esc(r.description||''),tag(r.status),money(r.opening_balance)])}else if(code==='REPORT_EXPENSE_SUMMARY'){headers=['Expense Account','Transactions','Total Amount'];rows=d.rows.map(r=>[esc(r.account),r.count,money(r.amount)])}else{headers=['Voucher No','Date','Type','Party','Main Account','Counter Account','Description','Method','Amount'];rows=d.rows.map(r=>[`<b>${esc(r.voucher_no)}</b>`,esc(r.voucher_date),tag(r.voucher_type),esc(r.party),esc(r.account_no+' — '+r.account_name),esc(r.counter_no+' — '+r.counter_name),esc(r.description||''),esc(r.method),money(r.amount)])}let total=d.rows.reduce((n,r)=>n+Number(r.amount||0),0);$('reportResult').innerHTML=`<div class="report-header"><h2>${esc(settings.organization_name||'Your Organization')}</h2><p>${esc(settings.address||'')} ${esc(settings.phone||'')}</p><h3>${esc(reportNames[code])}</h3><p>Period: ${esc(d.from)} to ${esc(d.to)}</p></div><div class="panel-head"><div><h3>${esc(reportNames[code])}</h3><p>${d.rows.length} record(s) · ${esc(d.from)} to ${esc(d.to)}</p></div>${code!=='REPORT_ACCOUNTS'?`<div class="report-total">Total: ${money(total)} ${esc(settings.currency||'PKR')}</div>`:''}</div>${table(headers,rows,'No records match this report criteria.')}`}catch(e){toast(e.message,true)}}function exportTableCsv(){let tableEl=$('reportResult')?.querySelector('table');if(!tableEl){toast('Generate a table report first.',true);return}let lines=[...tableEl.rows].map(r=>[...r.cells].map(c=>'"'+c.innerText.replace(/"/g,'""')+'"').join(','));let blob=new Blob([lines.join('\r\n')],{type:'text/csv;charset=utf-8;'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='emis-report.csv';a.click();URL.revokeObjectURL(url)}
function passwordPage(){$('pageContent').innerHTML=intro('Change Password','Keep your account secure by using a unique password.')+panel('Update Password',`<form id="passwordForm" class="form-grid"><div class="full-row"><label>Current Password</label><input name="old_password" type="password" required></div><div><label>New Password</label><input name="new_password" type="password" minlength="8" required></div><div class="form-actions full-row"><button class="btn primary">Change Password</button></div></form>`);$('passwordForm').onsubmit=async e=>{e.preventDefault();try{await api('changePassword',{},Object.fromEntries(new FormData(e.target)));toast('Password changed successfully.');e.target.reset()}catch(err){toast(err.message,true)}}}
function modal(title,content){$('modalRoot').innerHTML=`<div class="modal-backdrop" onclick="if(event.target===this)closeModal()"><div class="modal"><div class="modal-head"><h3>${esc(title)}</h3><button class="modal-x" onclick="closeModal()">×</button></div><div class="modal-body">${content}</div></div></div>`}function closeModal(){$('modalRoot').innerHTML=''}function printHtml(content){let w=window.open('','_blank');if(!w){toast('Allow pop-ups to print.',true);return}w.document.write(`<!doctype html><html><head><title>EMIS Print</title><style>body{font:13px Arial;color:#17263d;padding:30px}h2,h3{text-align:center}table{width:100%;border-collapse:collapse}td,th{border:1px solid #ddd;padding:8px;text-align:left}.report-header{text-align:center;margin-bottom:25px}</style></head><body>${content}<script>window.onload=()=>window.print()<\/script></body></html>`);w.document.close()}
