async function headsPage(){ $('pageContent').innerHTML=intro('Stock Head Setup','Create and maintain stock categories (Head Code is generated automatically).',`<button class="btn primary" onclick="headModal()">＋ New Head Entry</button>`)+panel('Stock Heads',`<div class="filter-row"><div class="field"><label>Search</label><input id="headQ" placeholder="Head code or name"></div><div class="field"><label>Status</label><select id="headStatus"><option value="">All statuses</option><option>Active</option><option>Inactive</option></select></div><button class="btn secondary" onclick="loadHeads()">Search</button></div><div id="headsTable"></div>`);await loadHeads()}
