async function headModal(id=0){let h=headCache.find(x=>Number(x.hcod)===Number(id))||{},code=h.hcod||'';if(!id){try{code=(await api('nextHeadCode')).hcod}catch(e){toast(e.message,true);return}}modal(id?'Edit Stock Head':'New Head Entry',`<form id="headForm" class="form-grid"><div><label>Head Code</label><input value="${esc(code)}" readonly></div><div><label>Head Name *</label><input name="hname" required maxlength="180" value="${esc(h.hname||'')}" placeholder="Enter full head name"></div><div><label>Status *</label><select name="hstatus"><option ${!h.hstatus||h.hstatus==='Active'?'selected':''}>Active</option><option ${h.hstatus==='Inactive'?'selected':''}>Inactive</option></select></div><div class="form-actions full-row"><button type="button" class="btn secondary" onclick="closeModal()">Cancel</button><button class="btn primary">Save Head</button></div></form>`);$('headForm').onsubmit=async e=>{e.preventDefault();try{await api('saveHead',{}, {...Object.fromEntries(new FormData(e.target)),hcod:id||0});closeModal();toast('Stock head saved.');await loadHeads()}catch(err){toast(err.message,true)}}}
async function productsPage(){$('pageContent').innerHTML=intro('Stock Product / Item Setup','Maintain products under each stock head, opening quantity, purchase price and current balance.',`<button class="btn primary" onclick="productModal()">＋ New Product / Item</button>`)+panel('Product Directory',`<div class="filter-row"><div class="field"><label>Search</label><input id="prodQ" placeholder="Product code, name or head"></div><div class="field"><label>Status</label><select id="prodStatus"><option value="">All statuses</option><option>Active</option><option>Inactive</option></select></div><button class="btn secondary" onclick="loadProducts()">Search</button></div><div id="productsTable"></div>`);await loadProducts()}
async function loadProducts(){try{let d=await api('products',{q:$('prodQ')?.value||'',status:$('prodStatus')?.value||''});productCache=d.data;headCache=d.heads;$('productsTable').innerHTML=table(['Product Code','Head','Product / Item Name','Size','Opening Qty','Price','Current Balance','Qty Mode','Status','Actions'],productCache.map(p=>[esc(p.pcod),esc(p.hname),`<b>${esc(p.pname)}</b>`,esc(p.psize||''),esc(p.pqty),money(p.pprice),esc(p.pbal),esc(p.pqmode),tag(p.pstatus),`<button class="btn secondary small" onclick="productModal(${p.pcod})">Edit</button>`]))}catch(e){toast(e.message,true)}}
async function productModal(id=0){let p=productCache.find(x=>Number(x.pcod)===Number(id))||{},code=p.pcod||'';if(!id){try{code=(await api('nextProductCode')).pcod}catch(e){toast(e.message,true);return}}if(!headCache.length){try{let d=await api('products');headCache=d.heads}catch(e){toast(e.message,true);return}}modal(id?'Edit Product / Item':'New Product / Item Entry',`<form id="productForm" class="form-grid"><div><label>Product Code</label><input value="${esc(code)}" readonly></div><div><label>Head Code / Name *</label><select name="hcod" required><option value="">Select stock head</option>${headCache.map(h=>`<option value="${h.hcod}" ${Number(h.hcod)===Number(p.hcod)?'selected':''}>${esc(h.hcod+' — '+h.hname)}</option>`).join('')}</select></div><div class="full-row"><label>Product / Item Name *</label><input name="pname" required value="${esc(p.pname||'')}" maxlength="180"></div><div><label>Product Size</label><input name="psize" value="${esc(p.psize||'')}"></div><div><label>Opening Quantity</label><input name="pqty" type="number" min="0" step="0.001" value="${p.pqty||0}" ${id?'readonly':''} ${id?'':'oninput="this.form.elements.pbal.value=this.value"'}></div><div><label>Unit Price</label><input name="pprice" type="number" min="0" step="0.01" value="${p.pprice||0}"></div><div><label>Current Quantity</label><input name="pbal" type="number" min="0" step="0.001" value="${p.pbal??p.pqty??0}" ${id?'readonly':'required'}></div><div><label>Quantity Mode</label><input name="pqmode" value="${esc(p.pqmode||'Qty')}" placeholder="Qty / Box / Pcs"></div><div><label>Status *</label><select name="pstatus"><option ${!p.pstatus||p.pstatus==='Active'?'selected':''}>Active</option><option ${p.pstatus==='Inactive'?'selected':''}>Inactive</option></select></div><div class="notice full-row">Product codes are generated automatically. A product is uniquely maintained by its Head Code and Product Code.</div><div class="form-actions full-row"><button type="button" class="btn secondary" onclick="closeModal()">Cancel</button><button class="btn primary">Save Product</button></div></form>`);$('productForm').onsubmit=async e=>{e.preventDefault();try{await api('saveProduct',{}, {...Object.fromEntries(new FormData(e.target)),pcod:id||0});closeModal();toast('Product saved successfully.');await loadProducts()}catch(err){toast(err.message,true)}}}
async function inventoryPage(type){let label=type==='Receiving'?'Receiving Stock Voucher':'Issue Stock Voucher';$('pageContent').innerHTML=intro(label,`Create, edit, cancel and print ${type.toLowerCase()} stock vouchers. Multiple products can be entered under one voucher number.`,`<button class="btn primary" onclick="inventoryModal('${type}')">＋ New ${label}</button>`)+panel(label+' Register',`<div class="filter-row"><div class="field"><label>Search Voucher / Account</label><input id="invQ" placeholder="Voucher no or account"></div><button class="btn secondary" onclick="loadInventory('${type}')">Search</button><button class="btn secondary" onclick="window.print()">Print Register</button></div><div id="inventoryTable"></div>`);await loadInventory(type)}
let inventoryCache=[];
async function loadInventory(type){try{let d=await api('inventoryVouchers',{type});inventoryCache=d.data;let q=($('invQ')?.value||'').toLowerCase();let rows=inventoryCache.filter(v=>(v.rrefno+' '+v.racno+' '+v.racname).toLowerCase().includes(q));$('inventoryTable').innerHTML=table(['Voucher No','Date','Account No','Account Name','Account Type','Products','Total Qty','Status','Actions'],rows.map(v=>[ `<b>${esc(v.rrefno)}</b>`,esc(v.rdate),esc(v.racno),esc(v.racname),esc(v.ractype),esc(v.item_count),esc(v.total_qty),tag(v.status),`${v.status==='Posted'?`<button class="btn secondary small" onclick="inventoryModal('${type}','${esc(v.rrefno)}')">Edit</button> <button class="btn danger small" onclick="cancelInventory('${type}','${esc(v.rrefno)}')">Cancel</button>`:''} <button class="btn secondary small" onclick="printInventory('${type}','${esc(v.rrefno)}')">Print</button>`]))}catch(e){toast(e.message,true)}}
function accountChanged(){let s=$('invAccount'),o=s.options[s.selectedIndex],v=o?.dataset;if(!v)return;$('invAccName').value=v.name||'';$('invAccType').value=v.type||'';$('invAccDes').value=v.des||''}
function productOptions(head,selected){return productCache.filter(p=>Number(p.hcod)===Number(head)&&p.pstatus==='Active').map(p=>`<option value="${p.pcod}" ${Number(p.pcod)===Number(selected)?'selected':''}>${esc(p.pcod+' — '+p.pname)}</option>`).join('')}
function renderInventoryLines(){let box=$('invLines');if(!box)return;box.innerHTML=inventoryLines.map((l,i)=>`<div class="inv-line" data-index="${i}"><div class="inv-line-head"><b>Product Line ${i+1}</b><button type="button" class="btn danger small" onclick="removeInvLine(${i})">Remove</button></div><div class="inv-line-grid"><div><label>Head Code / Name *</label><select onchange="invHeadChanged(${i},this.value)"><option value="">Select Head</option>${headCache.map(h=>`<option value="${h.hcod}" ${Number(l.rhcod)===Number(h.hcod)?'selected':''}>${esc(h.hcod+' — '+h.hname)}</option>`).join('')}</select></div><div><label>Product Code / Name *</label><select id="invProduct${i}" onchange="invProductChanged(${i},this.value)"><option value="">Select Product</option>${productOptions(l.rhcod,l.rpcod)}</select></div><div><label>Product Size</label><input value="${esc(l.rpsize||'')}" readonly></div><div><label>Available Balance</label><input value="${esc(l.available??'')}" readonly></div><div><label>Quantity *</label><input type="number" min="0.001" step="0.001" value="${esc(l.rpqty||'')}" onchange="inventoryLines[${i}].rpqty=this.value"></div><div><label>Unit Price</label><input value="${esc(l.rpprice??'')}" readonly></div><div><label>Quantity Mode</label><input value="${esc(l.rpqmode||'')}" readonly></div></div></div>`).join('');}
function invHeadChanged(i,v){inventoryLines[i].rhcod=v;inventoryLines[i].rpcod='';inventoryLines[i].rpname='';inventoryLines[i].rpsize='';inventoryLines[i].rpprice='';inventoryLines[i].rpqmode='';inventoryLines[i].available='';renderInventoryLines()}
function invProductChanged(i,v){let p=productCache.find(x=>Number(x.pcod)===Number(v)&&Number(x.hcod)===Number(inventoryLines[i].rhcod));if(!p)return;Object.assign(inventoryLines[i],{rpcod:p.pcod,rpname:p.pname,rpsize:p.psize,rpprice:p.pprice,rpqmode:p.pqmode,available:p.pbal,rpqty:inventoryLines[i].rpqty||''});renderInventoryLines()}
function addInvLine(){inventoryLines.push({rhcod:'',rpcod:'',rpqty:'',rpsize:'',rpprice:'',rpqmode:''});renderInventoryLines()}
function removeInvLine(i){inventoryLines.splice(i,1);renderInventoryLines()}
async function inventoryModal(type,ref=''){try{let [d,n]=await Promise.all([api('inventoryFormData',{type}),ref?api('inventoryVoucher',{type,ref}):api('nextInventoryRef',{type})]);inventoryAccounts=d.accounts;headCache=d.heads;productCache=d.products;let rows=ref?n.data:[];inventoryLines=rows.length?rows.map(r=>({rhcod:r.rhcod,rpcod:r.rpcod,rpname:r.rpname,rpsize:r.rpsize,rpqty:r.rpqty,rpprice:r.rpprice,rpqmode:r.rpqmode,available:r.rpbal})): [{rhcod:'',rpcod:'',rpqty:'',rpsize:'',rpprice:'',rpqmode:''}];let first=rows[0]||{};let refno=ref||n.ref;modal(ref?'Edit '+type+' Stock Voucher':'New '+type+' Stock Voucher',`<form id="inventoryForm"><div class="form-grid"><div><label>Voucher Reference No</label><input name="rrefno" value="${esc(refno)}" readonly></div><div><label>Voucher Date *</label><input name="rdate" type="date" required value="${esc(first.rdate||today())}"></div><div><label>Account No *</label><select id="invAccount" name="racno" required onchange="accountChanged()"><option value="">Select account</option>${inventoryAccounts.map(a=>`<option value="${esc(a.account_no)}" data-name="${esc(a.account_name)}" data-type="${esc(a.type_name)}" data-des="${esc(a.description||'')}" ${a.account_no===(first.racno||'')?'selected':''}>${esc(a.account_no+' — '+a.account_name)}</option>`).join('')}</select></div><div><label>Account Name</label><input id="invAccName" readonly value="${esc(first.racname||'')}"></div><div><label>Account Type</label><input id="invAccType" readonly value="${esc(first.ractype||'')}"></div><div class="full-row"><label>Account Description</label><input id="invAccDes" readonly value="${esc(first.racdes||'')}"></div></div><div class="panel-head inv-products-head"><h3>Voucher Products</h3><button type="button" class="btn secondary small" onclick="addInvLine()">＋ Add Product</button></div><div id="invLines"></div><div class="form-actions"><button type="button" class="btn secondary" onclick="closeModal()">Close</button><button class="btn primary">${ref?'Update Voucher':'Save Voucher'}</button></div></form>`);if(first.racno)accountChanged();renderInventoryLines();$('inventoryForm').onsubmit=async e=>{e.preventDefault();let account=$('invAccount');let payload={voucher_type:type,rrefno:refno,rdate:e.target.rdate.value,racno:account.value,items:inventoryLines.map(l=>({rhcod:l.rhcod,rpcod:l.rpcod,rpqty:l.rpqty})) ,edit:!!ref};try{if(payload.items.some(x=>!x.rhcod||!x.rpcod||Number(x.rpqty)<=0))throw new Error('Select Head, Product and enter a positive quantity on every line.');await api('saveInventoryVoucher',{},payload);closeModal();toast(type+' stock voucher saved successfully.');await loadInventory(type)}catch(err){toast(err.message,true)}}}catch(e){toast(e.message,true)}}
async function cancelInventory(type,ref){if(!confirm(`Cancel ${type.toLowerCase()} voucher ${ref}? Stock balances will be reversed and the ledger will retain the cancellation. `))return;try{await api('cancelInventoryVoucher',{}, {voucher_type:type,rrefno:ref});toast('Voucher cancelled and stock balance reversed.');await loadInventory(type)}catch(e){toast(e.message,true)}}
async function printInventory(type,ref){try{let d=await api('inventoryVoucher',{type,ref});let rows=d.data,first=rows[0];let body=rows.map((r,i)=>`<tr><td>${i+1}</td><td>${esc(r.rhname)}</td><td>${esc(r.rpcod)}</td><td>${esc(r.rpname)}</td><td>${esc(r.rpsize||'')}</td><td>${esc(r.rpqty)} ${esc(r.rpqmode)}</td><td>${money(r.rpprice)}</td><td>${money(Number(r.rpqty)*Number(r.rpprice))}</td></tr>`).join('');printHtml(`<div class="report-header"><h2>${esc(settings.organization_name||'Your Organization')}</h2><p>${esc(settings.address||'')} ${esc(settings.phone||'')}</p><h3>${type} Stock Voucher</h3></div><p><b>Reference:</b> ${esc(ref)} &nbsp; <b>Date:</b> ${esc(first.rdate)}</p><p><b>Account:</b> ${esc(first.racno+' — '+first.racname)} &nbsp; <b>Type:</b> ${esc(first.ractype)}</p><table><thead><tr><th>#</th><th>Head</th><th>Product Code</th><th>Product</th><th>Size</th><th>Qty</th><th>Unit Price</th><th>Amount</th></tr></thead><tbody>${body}</tbody></table><p style="text-align:right"><b>Total:</b> ${money(rows.reduce((s,r)=>s+Number(r.rpqty)*Number(r.rpprice),0))} ${esc(settings.currency||'PKR')}</p><p style="margin-top:70px">Prepared By: ______________ &nbsp; Received / Issued By: ______________ &nbsp; Approved By: ______________</p>`)}catch(e){toast(e.message,true)}}
async function stockLedgerPage(){
 $('pageContent').innerHTML=intro('Stock Ledger','Review every receipt, issue, opening adjustment and cancellation reversal by product.')+panel('Stock Ledger Filters',`<div class="filter-row"><div class="field"><label>Product Code / Name</label><select id="stockLedgerProduct" onchange="stockLedgerProductChanged()"><option value="">All Products</option></select></div><div class="field"><label>Product Name</label><input id="stockLedgerProductName" readonly placeholder="Auto populated"></div><div class="field"><label>From Date</label><input type="date" id="stockLedgerFrom"></div><div class="field"><label>To Date</label><input type="date" id="stockLedgerTo"></div><button class="btn primary" onclick="loadStockLedger()">View Ledger</button><button class="btn secondary" onclick="window.print()">Print</button></div><div id="stockLedgerTable"></div>`);
 await loadStockLedger();
}
function stockLedgerProductChanged(){let code=$('stockLedgerProduct').value;let p=stockLedgerProducts.find(x=>String(x.pcod)===String(code));$('stockLedgerProductName').value=p?p.pname:'';loadStockLedger();}
async function loadStockLedger(){
 try{
  let d=await api('stockLedger',{pcod:$('stockLedgerProduct')?.value||'',from:$('stockLedgerFrom')?.value||'',to:$('stockLedgerTo')?.value||''});
  stockLedgerProducts=d.products||stockLedgerProducts;
  let select=$('stockLedgerProduct'),selected=select.value;
  select.innerHTML='<option value="">All Products</option>'+stockLedgerProducts.map(p=>`<option value="${esc(p.pcod)}">${esc(p.pcod)} — ${esc(p.pname)}</option>`).join('');
  select.value=selected;
  let chosen=stockLedgerProducts.find(p=>String(p.pcod)===String(select.value));
  $('stockLedgerProductName').value=chosen?chosen.pname:'';
  $('stockLedgerTable').innerHTML=table(['Date','Reference','Transaction','Head','Product Code','Product','Qty In','Qty Out','Balance','Remarks'],d.data.map(r=>[esc(r.txn_date),esc(r.refno),tag(r.txn_type),esc(r.hname),esc(r.pcod),esc(r.pname),esc(r.qty_in),esc(r.qty_out),esc(r.balance),esc(r.remarks||'')]));
 }catch(e){toast(e.message,true)}
}

boot();
